//! Audited experimental opt-in and read-only Vulkan memory-size query only.
use ash::vk;
pub fn experimental(enabled:bool)->wgpu::ExperimentalFeatures{if enabled{unsafe{wgpu::ExperimentalFeatures::enabled()}}else{wgpu::ExperimentalFeatures::disabled()}}
pub fn required(adapter:&wgpu::Adapter,enabled:bool)->Result<wgpu::Features,String>{if !enabled{return Ok(wgpu::Features::empty())}if adapter.get_info().device_type==wgpu::DeviceType::Cpu||!adapter.features().contains(wgpu::Features::EXPERIMENTAL_RAY_QUERY){return Err("E_NATIVE_RAY_UNAVAILABLE: Vulkan hardware ray query unavailable; no CPU/software substitution".into())}Ok(wgpu::Features::EXPERIMENTAL_RAY_QUERY)}
pub fn bytes(device:&wgpu::Device,counts:&[u32],fast_trace:bool)->Result<u64,String>{unsafe{let d=device.as_hal::<wgpu::hal::api::Vulkan>().ok_or("E_NATIVE_RAY_UNAVAILABLE: Vulkan backend required")?;let raw=d.raw_device();let api=ash::khr::acceleration_structure::Device::new(d.shared_instance().raw_instance(),raw);let flags=if fast_trace{vk::BuildAccelerationStructureFlagsKHR::PREFER_FAST_TRACE}else{vk::BuildAccelerationStructureFlagsKHR::PREFER_FAST_BUILD};let mut total=0u64;for &count in counts{let triangle=vk::AccelerationStructureGeometryTrianglesDataKHR::default().vertex_format(vk::Format::R32G32B32_SFLOAT).vertex_stride(12).max_vertex(count-1).index_type(vk::IndexType::NONE_KHR);let geometry=vk::AccelerationStructureGeometryKHR::default().geometry_type(vk::GeometryTypeKHR::TRIANGLES).flags(vk::GeometryFlagsKHR::OPAQUE).geometry(vk::AccelerationStructureGeometryDataKHR{triangles:triangle});let info=vk::AccelerationStructureBuildGeometryInfoKHR::default().ty(vk::AccelerationStructureTypeKHR::BOTTOM_LEVEL).flags(flags).mode(vk::BuildAccelerationStructureModeKHR::BUILD).geometries(std::slice::from_ref(&geometry));let mut size=vk::AccelerationStructureBuildSizesInfoKHR::default();api.get_acceleration_structure_build_sizes(vk::AccelerationStructureBuildTypeKHR::DEVICE,&info,&[count/3],&mut size);total=total.checked_add(size.acceleration_structure_size).and_then(|v|v.checked_add(size.build_scratch_size)).ok_or("E_NATIVE_RAY_BUDGET: AS byte overflow")?;}
 let instances=vk::AccelerationStructureGeometryInstancesDataKHR::default().array_of_pointers(false);let geometry=vk::AccelerationStructureGeometryKHR::default().geometry_type(vk::GeometryTypeKHR::INSTANCES).geometry(vk::AccelerationStructureGeometryDataKHR{instances});let info=vk::AccelerationStructureBuildGeometryInfoKHR::default().ty(vk::AccelerationStructureTypeKHR::TOP_LEVEL).flags(flags).mode(vk::BuildAccelerationStructureModeKHR::BUILD).geometries(std::slice::from_ref(&geometry));let mut size=vk::AccelerationStructureBuildSizesInfoKHR::default();api.get_acceleration_structure_build_sizes(vk::AccelerationStructureBuildTypeKHR::DEVICE,&info,&[counts.len()as u32],&mut size);total.checked_add(size.acceleration_structure_size).and_then(|v|v.checked_add(size.build_scratch_size)).ok_or("E_NATIVE_RAY_BUDGET: AS byte overflow".into())}}
